class TrackedObject implements AutoCloseable {
    public String label;

    public TrackedObject(String label) {
        this.label = label;
    }

    @Override
    public void close() {
        System.out.println(label + " closed");
    }
}

// In main:
try (TrackedObject a = new TrackedObject("Alpha")) {
    // Alpha will be closed automatically when this block ends
}
TrackedObject b = new TrackedObject("Beta");
System.out.println(b.label); // Beta must still be accessible
System.out.println("Done");

